pygments.lexers._postgres_builtins.parse:
def parse_keywords(f):
    kw = []
    for m in re.finditer('PG_KEYWORD\\("(.+?)"', f):
        kw.append(m.group(1).upper())
    if not kw:
        raise ValueError('no keyword found')
    kw.sort()
    return kw

pygments.lexers._mysql_builtins.parse_le:
def parse_lex_keywords(f):
    """Parse keywords in lex.h."""
    results = set()
    for m in re.finditer('{SYM(?:_HK)?\\("(?P<keyword>[a-z0-9_]+)",', f, flags=re.I):
        results.add(m.group('keyword').lower())
    if not results:
        raise ValueError('No keywords found')
    return results

pygments.formatters.__init__._fn_matches:
def _fn_matches(fn, glob):
    """Return whether the supplied file name fn matches pattern filename."""
    if glob not in _pattern_cache:
        pattern = _pattern_cache[glob] = re.compile(fnmatch.translate(glob))
        return pattern.match(fn)
    return _pattern_cache[glob].match(fn)

pygments.lexers._php_builtins.get_php_fu:
def get_php_functions():
    function_re = re.compile(PHP_FUNCTION_RE)
    module_re = re.compile(PHP_MODULE_RE)
    modules = {}
    for file in get_php_references():
        module = ''
        with open(file, encoding='utf-8') as f:
            for line in f:
                if not module:
                    search = module_re.search(line)
                    if search:
                        module = search.group(1)
                        modules[module] = []
                elif 'href="function.' in line:
                    for match in function_re.finditer(line):
                        fn = match.group(1)
                        if ('»' not in fn and '«' not in fn and '::' not in fn and '\\' not in fn and fn not in modules[module]):
                            modules[module].append(fn)
        if module:
            if module == 'Filesystem':
                modules[module].remove('delete')
            if not modules[module]:
                del modules[module]
    for key in modules:
        modules[key] = tuple(modules[key])
    return modules

pygments.lexers._lua_builtins.get_lua_fu:
def get_lua_functions(version):
    f = urlopen(f'http://www.lua.org/manual/{version}/')
    r = re.compile('^<A HREF="manual.html#pdf-(?!lua|LUA)([^:]+)">\\1</A>')
    functions = []
    for line in f:
        m = r.match(line.decode('iso-8859-1'))
        if m is not None:
            functions.append(m.groups()[0])
    return functions

pygments.lexers.lilypond.builtin_words:
def builtin_words(names, backslash, suffix=NAME_END_RE):
    prefix = '[\\-_^]?'
    if backslash == 'mandatory':
        prefix += '\\\\'
    elif backslash == 'optional':
        prefix += '\\\\?'
    else:
        assert backslash == 'disallowed'
    return words(names, prefix, suffix)

pygments.lexers._lua_builtins.get_newest:
def get_newest_version():
    f = urlopen('http://www.lua.org/manual/')
    r = re.compile('^<A HREF="(\\d\\.\\d)/">(Lua )?\\1</A>')
    for line in f:
        m = r.match(line.decode('iso-8859-1'))
        if m is not None:
            return m.groups()[0]

pygments.cmdline._parse_options:
def _parse_options(o_strs):
    opts = {}
    if not o_strs:
        return opts
    for o_str in o_strs:
        if not o_str.strip():
            continue
        o_args = o_str.split(',')
        for o_arg in o_args:
            o_arg = o_arg.strip()
            try:
                (o_key, o_val) = o_arg.split('=', 1)
                o_key = o_key.strip()
                o_val = o_val.strip()
            except ValueError:
                opts[o_arg] = True
            else:
                opts[o_key] = o_val
    return opts

pygments.lexers.__init__._iter_lexerclas:
def _iter_lexerclasses(plugins=True):
    """Return an iterator over all lexer classes."""
    for key in sorted(LEXERS):
        (module_name, name) = LEXERS[key][:2]
        if name not in _lexer_cache:
            _load_lexers(module_name)
        yield _lexer_cache[name]
    if plugins:
        yield from find_plugin_lexers()

pygments.filters.__init__.find_filter_cl:
def find_filter_class(filtername):
    """Lookup a filter by name. Return None if not found."""
    if filtername in FILTERS:
        return FILTERS[filtername]
    for (name, cls) in find_plugin_filters():
        if name == filtername:
            return cls
    return None
